Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Normalize-RelativePath {
    param([string] $Path)

    $trimmed = $Path.Trim()
    while ($trimmed.StartsWith('.\') -or $trimmed.StartsWith('./')) {
        $trimmed = $trimmed.Substring(2)
    }

    return ($trimmed -replace '\\', '/').TrimStart('/')
}

function Test-RelevantRecoveryPath {
    param([string] $RelativePath)

    return $RelativePath -match '^postgres/pg1[89]-.+\.sql$' -or
        $RelativePath -match '^falkordb-dump\.rdb$' -or
        $RelativePath -match '^garage/kubeblocks-backups/pg18/pg18/base/[^/]+/(backup\.info|data\.tar)$' -or
        $RelativePath -match '^garage/kubeblocks-backups/pg18/pg18/wals/.+$' -or
        $RelativePath -match '^garage/kubeblocks-backups/data-platform/[^/]+/falkordb/[^/]+/(kubeblocks-backup\.json|falkordb-datafile-.+\.tar\.zst)$'
}

function Get-RecoveryCategory {
    param([string] $RelativePath)

    if ($RelativePath -match '^postgres/pg1[89]-.+\.sql$') { return 'PostgresLogicalDump' }
    if ($RelativePath -match '^falkordb-dump\.rdb$') { return 'FalkorDirectDump' }
    if ($RelativePath -match '^garage/kubeblocks-backups/pg18/pg18/base/[^/]+/backup\.info$') { return 'Pg18BaseBackupInfo' }
    if ($RelativePath -match '^garage/kubeblocks-backups/pg18/pg18/base/[^/]+/data\.tar$') { return 'Pg18BaseBackupData' }
    if ($RelativePath -match '^garage/kubeblocks-backups/pg18/pg18/wals/.+\.history$') { return 'Pg18WalHistory' }
    if ($RelativePath -match '^garage/kubeblocks-backups/pg18/pg18/wals/.+$') { return 'Pg18WalSegment' }
    if ($RelativePath -match '^garage/kubeblocks-backups/data-platform/[^/]+/falkordb/[^/]+/kubeblocks-backup\.json$') { return 'FalkorBackupMetadata' }
    if ($RelativePath -match '^garage/kubeblocks-backups/data-platform/[^/]+/falkordb/[^/]+/falkordb-datafile-.+\.tar\.zst$') { return 'FalkorBackupArchive' }

    return 'Unknown'
}

function Get-ManifestChecksums {
    param([string] $RootPath)

    $manifestPath = Join-Path $RootPath 'SHA256SUMS.txt'
    $checksums = @{}
    if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
        return $checksums
    }

    foreach ($line in Get-Content -LiteralPath $manifestPath) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        if ($line -notmatch '^(?<hash>[A-Fa-f0-9]{64})\s+\*?(?<path>.+?)\s*$') { continue }

        $checksums[(Normalize-RelativePath -Path $Matches.path)] = $Matches.hash.ToUpperInvariant()
    }

    return $checksums
}

$results = New-Object System.Collections.Generic.List[object]
foreach ($rootPath in $Root) {
    if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) {
        $results.Add([pscustomobject]@{
                Root             = $rootPath
                RelativePath     = $null
                FullPath         = $null
                Category         = $null
                LengthBytes      = $null
                LastWriteTimeUtc = $null
                Sha256           = $null
                ChecksumSource   = 'Unavailable'
                Availability     = 'Missing'
            })
        continue
    }

    $resolvedRoot = (Resolve-Path -LiteralPath $rootPath).Path
    $manifestChecksums = Get-ManifestChecksums -RootPath $resolvedRoot
    Get-ChildItem -LiteralPath $resolvedRoot -Recurse -File -ErrorAction Stop |
        ForEach-Object {
            $relativePath = Normalize-RelativePath -Path $_.FullName.Substring($resolvedRoot.Length).TrimStart('\', '/')
            if (-not (Test-RelevantRecoveryPath -RelativePath $relativePath)) { return }

            $sha = $null
            $checksumSource = 'FileHash'
            if ($manifestChecksums.ContainsKey($relativePath)) {
                $sha = $manifestChecksums[$relativePath]
                $checksumSource = 'Manifest'
            }
            else {
                $sha = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToUpperInvariant()
            }

            $results.Add([pscustomobject]@{
                    Root             = $resolvedRoot
                    RelativePath     = $relativePath
                    FullPath         = $_.FullName
                    Category         = Get-RecoveryCategory -RelativePath $relativePath
                    LengthBytes      = $_.Length
                    LastWriteTimeUtc = $_.LastWriteTimeUtc
                    Sha256           = $sha
                    ChecksumSource   = $checksumSource
                    Availability     = 'Available'
                })
        }
}

$results

