        $todoCards = $plan | Where-Object { $_.Kind -eq 'PostgresDump' -and $_.DatabaseName -eq 'todo_cards' }

        $soil.Root | Should Be (Resolve-Path -LiteralPath $july11).Path
        $todoCards.Root | Should Be (Resolve-Path -LiteralPath $july8).Path
