[CmdletBinding()]
param(
    [Parameter()]
    [string] $InputFile,

    [Parameter(Mandatory)]
    [ValidatePattern('^[a-z][a-z0-9_]*$')]
    [string] $Role,

    [Parameter()]
    [ValidateSet('Standard', 'Corpus', 'TodoCards')]
    [string] $Profile = 'Standard'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$utf8NoBom = [System.Text.UTF8Encoding]::new($false)
$reader = if ($InputFile) {
    [System.IO.StreamReader]::new([System.IO.File]::OpenRead((Resolve-Path -LiteralPath $InputFile).Path), [System.Text.Encoding]::UTF8, $true, 65536)
}
else {
    [System.IO.StreamReader]::new([Console]::OpenStandardInput(), [System.Text.Encoding]::UTF8, $true, 65536)
}
$writer = [System.IO.StreamWriter]::new([Console]::OpenStandardOutput(), $utf8NoBom, 65536, $true)

$quotedRole = '"' + $Role.Replace('"', '""') + '"'
$skipStatement = $false
$copyMode = 'None'

function Test-StatementTerminator {
    param([string] $Line)
    return $Line.TrimEnd().EndsWith(';', [StringComparison]::Ordinal)
}

function Test-FilteredStatement {
    param([string] $Line)

    return $Line -match '^\s*(CREATE|ALTER|COMMENT\s+ON)\s+EXTENSION\b' -or
        $Line -match '^\s*(GRANT|REVOKE)\b' -or
        $Line -match '^\s*ALTER\s+DEFAULT\s+PRIVILEGES\b' -or
        $Line -match '^\s*ALTER\s+.+\s+OWNER\s+TO\s+' -or
        $Line -match '^\s*SET\s+SESSION\s+AUTHORIZATION\b' -or
        $Line -match '^\s*(SET|RESET)\s+ROLE\b' -or
        $Line -match '^\s*CREATE\s+USER\s+MAPPING\b' -or
        $Line -match '^\s*CREATE\s+SERVER\s+market_live_fdw_server\b' -or
        $Line -match '^\s*CREATE\s+DATABASE\b' -or
        $Line -match '^\s*ALTER\s+DATABASE\b' -or
        $Line -match '^\s*\\connect\b' -or
        $Line -match '^\s*(CREATE|ALTER|COMMENT\s+ON)\s+SCHEMA\s+(tokenizer_catalog|bm25_catalog)\b'
}

function Test-TimescaleOwnedRelationStatement {
    param([string] $Line)

    $timescaleRelation = '"?_timescaledb_[A-Za-z0-9_$]*"?\."?[A-Za-z0-9_$]+"?'
    $relationSuffix = '(?:\s|[;(]|$)'

    return $Line -match ('^\s*COPY\s+' + $timescaleRelation + $relationSuffix) -or
        $Line -match ('^\s*(?:CREATE|ALTER|DROP)\s+(?:TABLE|SEQUENCE|VIEW|MATERIALIZED\s+VIEW|FUNCTION|TYPE)\s+(?:IF\s+(?:NOT\s+)?EXISTS\s+)?(?:ONLY\s+)?' + $timescaleRelation + $relationSuffix) -or
        $Line -match ('^\s*COMMENT\s+ON\s+(?:TABLE|SEQUENCE|VIEW|MATERIALIZED\s+VIEW|FUNCTION|TYPE)\s+' + $timescaleRelation + $relationSuffix) -or
        $Line -match ('^\s*CREATE\s+(?:UNIQUE\s+)?INDEX(?:\s+CONCURRENTLY)?\s+\S+\s+ON\s+(?:ONLY\s+)?' + $timescaleRelation + $relationSuffix) -or
        $Line -match ('^\s*CREATE\s+TRIGGER\s+\S+.*?\s+ON\s+' + $timescaleRelation + $relationSuffix)
}

function Test-CorpusOwnedRelationStatement {
    param([string] $Line)

    $catalogSchema = '(?:"(?:_timescaledb_[A-Za-z0-9_$]*|tokenizer_catalog|bm25_catalog)"|(?:_timescaledb_[A-Za-z0-9_$]*|tokenizer_catalog|bm25_catalog))'
    $identifier = '(?:"(?:[^"]|"")+"|[A-Za-z_][A-Za-z0-9_$]*)'
    $catalogRelation = $catalogSchema + '\.' + $identifier
    $relationSuffix = '(?:\s|[;(,]|$)'

    return $Line -match ('^\s*(?:COPY|INSERT\s+INTO|UPDATE|DELETE\s+FROM|MERGE\s+INTO|TRUNCATE(?:\s+TABLE)?)\s+(?:ONLY\s+)?' + $catalogRelation + $relationSuffix) -or
        $Line -match ('^\s*(?:CREATE(?:\s+OR\s+REPLACE)?|ALTER|DROP)\s+(?:TABLE|SEQUENCE|VIEW|MATERIALIZED\s+VIEW|FOREIGN\s+TABLE|FUNCTION|PROCEDURE|TYPE|DOMAIN)\s+(?:IF\s+(?:NOT\s+)?EXISTS\s+)?(?:ONLY\s+)?' + $catalogRelation + $relationSuffix) -or
        $Line -match ('^\s*(?:ALTER|DROP)\s+INDEX\s+(?:IF\s+EXISTS\s+)?' + $catalogRelation + $relationSuffix) -or
        $Line -match ('^\s*COMMENT\s+ON\s+(?:TABLE|SEQUENCE|VIEW|MATERIALIZED\s+VIEW|FOREIGN\s+TABLE|FUNCTION|PROCEDURE|TYPE|DOMAIN|COLUMN)\s+' + $catalogRelation + '(?:\.' + $identifier + ')?' + $relationSuffix) -or
        $Line -match ('^\s*CREATE\s+(?:UNIQUE\s+)?INDEX(?:\s+CONCURRENTLY)?(?:\s+IF\s+NOT\s+EXISTS)?\s+\S+\s+ON\s+(?:ONLY\s+)?' + $catalogRelation + $relationSuffix) -or
        $Line -match ('^\s*CREATE(?:\s+OR\s+REPLACE)?\s+TRIGGER\s+\S+.*?\s+ON\s+' + $catalogRelation + $relationSuffix) -or
        $Line -match ('^\s*(?:CREATE|ALTER|DROP)\s+(?:POLICY|RULE)\s+.*?\s+ON\s+' + $catalogRelation + $relationSuffix) -or
        $Line -match ('^\s*(?:CREATE|ALTER|DROP|COMMENT\s+ON)\s+SCHEMA\s+(?:IF\s+(?:NOT\s+)?EXISTS\s+)?' + $catalogSchema + '(?:\s|;|$)') -or
        $Line -match ("^\s*SELECT\s+(?:pg_catalog\.)?setval\(\s*'" + $catalogRelation + "'")
}

try {
    $writer.WriteLine("SET ROLE $quotedRole;")

    while (($line = $reader.ReadLine()) -ne $null) {
        if ($copyMode -ne 'None') {
            if ($copyMode -ne 'Skip') { $writer.WriteLine($line) }
            if ($line.Trim() -eq '\.') {
                if ($copyMode -eq 'Privileged') { $writer.WriteLine("SET ROLE $quotedRole;") }
                $copyMode = 'None'
            }
            continue
        }

        if ($skipStatement) {
            if (Test-StatementTerminator -Line $line) { $skipStatement = $false }
            continue
        }

        if (Test-FilteredStatement -Line $line) {
            if (-not (Test-StatementTerminator -Line $line)) { $skipStatement = $true }
            continue
        }

        if ($line -match '^\s*COPY\s+.+\s+FROM\s+stdin;\s*$') {
            if ($Profile -eq 'TodoCards' -and (Test-TimescaleOwnedRelationStatement -Line $line)) {
                $copyMode = 'Skip'
                continue
            }
            if ($Profile -eq 'Corpus' -and (Test-CorpusOwnedRelationStatement -Line $line)) {
                $writer.WriteLine('RESET ROLE;')
                $writer.WriteLine($line)
                $copyMode = 'Privileged'
                continue
            }

            $writer.WriteLine($line)
            $copyMode = 'Ordinary'
            continue
        }

        if ($Profile -eq 'TodoCards' -and (Test-TimescaleOwnedRelationStatement -Line $line)) {
            if (-not (Test-StatementTerminator -Line $line)) { $skipStatement = $true }
            continue
        }

        if ($Profile -eq 'Corpus' -and (Test-CorpusOwnedRelationStatement -Line $line)) {
            $writer.WriteLine('RESET ROLE;')
            $writer.WriteLine($line)
            if (Test-StatementTerminator -Line $line) {
                $writer.WriteLine("SET ROLE $quotedRole;")
            }
            else {
                while (($continuation = $reader.ReadLine()) -ne $null) {
                    $writer.WriteLine($continuation)
                    if (Test-StatementTerminator -Line $continuation) { break }
                }
                $writer.WriteLine("SET ROLE $quotedRole;")
            }
            continue
        }

        $writer.WriteLine($line)
    }

    if ($copyMode -ne 'None' -or $skipStatement) {
        throw 'The PostgreSQL dump ended inside an unfinished statement or COPY block.'
    }

    $writer.WriteLine('RESET ROLE;')
    $writer.Flush()
}
finally {
    $reader.Dispose()
    $writer.Dispose()
}

