Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-LogicalDumpInfo {
    param([System.IO.FileInfo] $File)

    if ($File.Name -notmatch '^(?<engine>pg1[89])-(?<database>[a-z0-9_]+)\.sql$') {
        return $null
    }

    [pscustomobject]@{
        EngineVersion = $Matches.engine
        DatabaseName  = $Matches.database
        FullPath      = $File.FullName
        LengthBytes   = $File.Length
    }
}

function Select-RecoveryCandidate {
    param(
        [Parameter(Mandatory)]
        [object[]] $Candidates,

        [Parameter(Mandatory)]
        [string] $Description,

        [Parameter()]
        [string] $PreferredRootPath
    )

    if ($Candidates.Count -eq 1) {
        return $Candidates[0]
    }

    if ([string]::IsNullOrWhiteSpace($PreferredRootPath)) {
        $paths = $Candidates.FullPath -join '; '
        throw "Ambiguous recovery inputs detected. Supply -PreferredRoot to select a duplicate. ${Description}: $paths"
    }

    $preferredCandidates = @($Candidates | Where-Object { $_.Root -eq $PreferredRootPath })
    if ($preferredCandidates.Count -eq 1) {
        return $preferredCandidates[0]
    }

    $paths = $Candidates.FullPath -join '; '
    throw "Ambiguous recovery inputs detected. Preferred root '$PreferredRootPath' does not select one ${Description}: $paths"
}

$resolvedRoots = New-Object System.Collections.Generic.List[string]
foreach ($rootPath in $Root) {
    if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) {
        throw "Recovery root not found: $rootPath"
    }

    $resolvedRoot = (Resolve-Path -LiteralPath $rootPath).Path
    if (-not $resolvedRoots.Contains($resolvedRoot)) {
        $resolvedRoots.Add($resolvedRoot)
    }
}

$preferredRootPath = $null
if ($PreferredRoot) {
    if (-not (Test-Path -LiteralPath $PreferredRoot -PathType Container)) {
        throw "Preferred recovery root not found: $PreferredRoot"
    }

    $preferredRootPath = (Resolve-Path -LiteralPath $PreferredRoot).Path
    if (-not $resolvedRoots.Contains($preferredRootPath)) {
        throw "Preferred recovery root must be included in -Root: $preferredRootPath"
    }
}

$postgresCandidates = New-Object System.Collections.Generic.List[object]
$falkorCandidates = New-Object System.Collections.Generic.List[object]

foreach ($resolvedRoot in $resolvedRoots) {
    $postgresDir = Join-Path $resolvedRoot 'postgres'
    if (Test-Path -LiteralPath $postgresDir -PathType Container) {
        Get-ChildItem -LiteralPath $postgresDir -File -Filter '*.sql' |
            ForEach-Object {
                $info = Get-LogicalDumpInfo -File $_
                if ($null -ne $info) {
                    $postgresCandidates.Add([pscustomobject]@{
                            Root          = $resolvedRoot
                            Kind          = 'PostgresDump'
                            EngineVersion = $info.EngineVersion
                            DatabaseName  = $info.DatabaseName
                            FullPath      = $info.FullPath
                            LengthBytes   = $info.LengthBytes
                        })
                }
            }
    }

    $falkorDump = Join-Path $resolvedRoot 'falkordb-dump.rdb'
    if (Test-Path -LiteralPath $falkorDump -PathType Leaf) {
        $item = Get-Item -LiteralPath $falkorDump
        $falkorCandidates.Add([pscustomobject]@{
                Root          = $resolvedRoot
                Kind          = 'FalkorDump'
                EngineVersion = 'falkordb'
                DatabaseName  = 'default'
                FullPath      = $item.FullName
                LengthBytes   = $item.Length
            })
    }
}

$selectedCandidates = New-Object System.Collections.Generic.List[object]
foreach ($group in ($postgresCandidates | Group-Object { '{0}/{1}' -f $_.EngineVersion, $_.DatabaseName })) {
    $selectedCandidates.Add((Select-RecoveryCandidate -Candidates @($group.Group) -Description $group.Name -PreferredRootPath $preferredRootPath))
}

if ($falkorCandidates.Count -gt 0) {
    $selectedCandidates.Add((Select-RecoveryCandidate -Candidates $falkorCandidates.ToArray() -Description 'FalkorDB dump' -PreferredRootPath $preferredRootPath))
}

foreach ($candidate in $selectedCandidates | Sort-Object Kind, EngineVersion, DatabaseName) {
    [pscustomobject]@{
        Root           = $candidate.Root
        Kind           = $candidate.Kind
        EngineVersion  = $candidate.EngineVersion
        DatabaseName   = $candidate.DatabaseName
        FullPath       = $candidate.FullPath
        LengthBytes    = $candidate.LengthBytes
        ConvertRole    = if ($candidate.Kind -eq 'PostgresDump') { $candidate.DatabaseName } else { $null }
        ConvertProfile = if ($candidate.Kind -ne 'PostgresDump') {
            $null
        }
        else {
            switch ($candidate.DatabaseName) {
                'llm_measurements' { 'Corpus' }
                'todo_cards' { 'TodoCards' }
                default { 'Standard' }
            }
        }
    }
}

