function Invoke-ConvertPgDump {
    param(
        [string] $InputFile,
        [string] $Role,
        [string] $Profile
    )

    & powershell.exe -NoProfile -File $scriptPath -InputFile $InputFile -Role $Role -Profile $Profile | Out-String
}

Describe 'Convert-PgDump.ps1' {
    It 'filters ownership and grant statements in the Standard profile' {
        $inputPath = Join-Path $TestDrive 'standard.sql'
        @'
CREATE DATABASE sample;
ALTER TABLE public.widgets OWNER TO old_owner;
GRANT SELECT ON TABLE public.widgets TO reader;
INSERT INTO public.widgets VALUES (1);
'@ | Set-Content -LiteralPath $inputPath -NoNewline

        $output = Invoke-ConvertPgDump -InputFile $inputPath -Role app_owner -Profile Standard

        $output | Should Match '^SET ROLE "app_owner";'
        $output | Should Not Match 'CREATE DATABASE'
        $output | Should Not Match 'OWNER TO'
        $output | Should Not Match '^GRANT '
        $output | Should Match 'INSERT INTO public\.widgets VALUES \(1\);'
        $output | Should Match 'RESET ROLE;'
    }

    It 'temporarily resets role for extension catalog COPY rows in the Corpus profile' {
        $inputPath = Join-Path $TestDrive 'corpus.sql'
        @'
COPY tokenizer_catalog.dictionary FROM stdin;
row-1
\.
INSERT INTO public.documents VALUES (1);
'@ | Set-Content -LiteralPath $inputPath -NoNewline

        $output = Invoke-ConvertPgDump -InputFile $inputPath -Role corpus_owner -Profile Corpus

        $output | Should Match 'SET ROLE "corpus_owner";'
        $output | Should Match 'RESET ROLE;'
        $output | Should Match 'COPY tokenizer_catalog\.dictionary FROM stdin;'
        $output | Should Match 'row-1'
        $output | Should Match 'INSERT INTO public\.documents VALUES \(1\);'
        ([regex]::Matches($output, 'SET ROLE "corpus_owner";')).Count | Should Be 2
    }

    It 'temporarily resets role for extension catalog SQL targets in the Corpus profile' {
        $inputPath = Join-Path $TestDrive 'corpus-catalog-sql.sql'
        @'
CREATE TABLE bm25_catalog.terms (id integer);
INSERT INTO tokenizer_catalog.dictionary VALUES (1);
'@ | Set-Content -LiteralPath $inputPath -NoNewline

        $output = Invoke-ConvertPgDump -InputFile $inputPath -Role corpus_owner -Profile Corpus

        $output | Should Match 'CREATE TABLE bm25_catalog\.terms \(id integer\);'
        $output | Should Match 'INSERT INTO tokenizer_catalog\.dictionary VALUES \(1\);'
        ([regex]::Matches($output, 'SET ROLE "corpus_owner";')).Count | Should Be 3
        ([regex]::Matches($output, 'RESET ROLE;')).Count | Should Be 3
    }

    It 'keeps ordinary Corpus SQL under the application role when values contain catalog markers' {
        $inputPath = Join-Path $TestDrive 'corpus-ordinary-sql.sql'
        @'
CREATE TABLE public.documents (body text DEFAULT '_timescaledb_catalog.foo');
INSERT INTO public.documents VALUES ('bm25_catalog.term');
'@ | Set-Content -LiteralPath $inputPath -NoNewline

        $output = Invoke-ConvertPgDump -InputFile $inputPath -Role corpus_owner -Profile Corpus

        $output | Should Match "CREATE TABLE public\.documents \(body text DEFAULT '_timescaledb_catalog\.foo'\);"
        $output | Should Match "INSERT INTO public\.documents VALUES \('bm25_catalog\.term'\);"
        ([regex]::Matches($output, 'SET ROLE "corpus_owner";')).Count | Should Be 1
        ([regex]::Matches($output, 'RESET ROLE;')).Count | Should Be 1
    }

    It 'keeps ordinary Corpus COPY under the application role when its header and data contain catalog markers' {
        $inputPath = Join-Path $TestDrive 'corpus-ordinary-copy.sql'
        @'
COPY public.documents (tokenizer_catalog_note, body) FROM stdin;
_timescaledb_catalog.foo	bm25_catalog.term
\.
'@ | Set-Content -LiteralPath $inputPath -NoNewline

        $output = Invoke-ConvertPgDump -InputFile $inputPath -Role corpus_owner -Profile Corpus

        $output | Should Match 'COPY public\.documents \(tokenizer_catalog_note, body\) FROM stdin;'
        $output | Should Match '_timescaledb_catalog\.foo\s+bm25_catalog\.term'
        ([regex]::Matches($output, 'SET ROLE "corpus_owner";')).Count | Should Be 1
        ([regex]::Matches($output, 'RESET ROLE;')).Count | Should Be 1
    }

    It 'skips Timescale statements and COPY blocks in the TodoCards profile' {
        $inputPath = Join-Path $TestDrive 'todo.sql'
        @'
CREATE TABLE _timescaledb_catalog.foo (id integer);
COPY _timescaledb_catalog.foo FROM stdin;
1
\.
INSERT INTO public.todo_cards VALUES (1);
'@ | Set-Content -LiteralPath $inputPath -NoNewline

        $output = Invoke-ConvertPgDump -InputFile $inputPath -Role todo_owner -Profile TodoCards

        $output | Should Not Match '_timescaledb_catalog'
        $output | Should Match 'INSERT INTO public\.todo_cards VALUES \(1\);'
    }

    It 'keeps ordinary SQL and COPY data when a string literal contains the Timescale marker' {
        $inputPath = Join-Path $TestDrive 'todo-marker-literal.sql'
        @'
CREATE TABLE _timescaledb_catalog.foo (id integer);
COPY _timescaledb_internal.chunk FROM stdin;
1
\.
CREATE TABLE public.notes (body text DEFAULT '_timescaledb_catalog.foo');
INSERT INTO public.notes VALUES ('_timescaledb_catalog.foo');
COPY public.notes FROM stdin;
ordinary row with _timescaledb_catalog.foo
\.
'@ | Set-Content -LiteralPath $inputPath -NoNewline

        $output = Invoke-ConvertPgDump -InputFile $inputPath -Role todo_owner -Profile TodoCards

        $output | Should Not Match 'CREATE TABLE _timescaledb_catalog\.foo'
        $output | Should Not Match 'COPY _timescaledb_internal\.chunk'
        $output | Should Match "CREATE TABLE public\.notes \(body text DEFAULT '_timescaledb_catalog\.foo'\);"
        $output | Should Match "INSERT INTO public\.notes VALUES \('_timescaledb_catalog\.foo'\);"
        $output | Should Match 'COPY public\.notes FROM stdin;'
        $output | Should Match 'ordinary row with _timescaledb_catalog\.foo'
    }
}

